class BioImageBase(MetaTensor, TensorImage, metaclass=MetaResolver):
    """
    Base class for bioimaging data.

    Provides:
    - MetaTensor integration
    - visualization utilities
    - lightweight tensor wrapper

    """

    _bypass_type = torchTensor
    _show_args = {"cmap": "gray"}
    _channels="CZYX"
    _transforms = None
    _keys = []

    # --------------------------------------------------
    # BASIC CONSTRUCTORS
    # --------------------------------------------------
    @classmethod
    def from_tensor(cls, x: torchTensor, meta: dict | None = None):
        return cls(x=x, meta=meta or {})

    def as_tensor(self) -> torchTensor:
        return self.as_subclass(torchTensor)
    
    # --------------------------------------------------
    # TRANSFORMS CONFIG
    # --------------------------------------------------
    @classmethod
    def item_preprocessing(cls, transforms):
        cls._transforms = transforms

    # --------------------------------------------------
    # LOADING
    # --------------------------------------------------
    create = classmethod(_create)
    
    # --------------------------------------------------
    # MONAI INTEGRATION
    # --------------------------------------------------
    @classmethod
    def load(cls,**kwargs) -> Callable:
        def _load(fn):
            if isinstance(fn, torchTensor):
                return cls.from_tensor(fn)

            local_kwargs = dict(kwargs)
            local_kwargs.setdefault("channels", cls._channels)
            local_kwargs.setdefault("transforms", cls._transforms)

            return image_reader(
                fn,
                output="metatensor",
                **local_kwargs,
            )

        return _load

    @classmethod
    def load_dict(cls, **kwargs) -> Callable:
        def _load_dict(data: dict|Sequence[dict]):

            local_kwargs = dict(kwargs)
            local_kwargs.setdefault("keys", cls._keys)
            local_kwargs.setdefault("channels", cls._channels)
            local_kwargs.setdefault("transforms", cls._transforms)

            return image_reader_dict(
                data,
                **local_kwargs,
            )

        return _load_dict

    # --------------------------------------------------
    # VISUALIZATION
    # --------------------------------------------------
    def show(self, ctx=None, figsize=None, title=None, **kwargs):
        return show_biodata(
            self,
            ctx=ctx,
            title=[title],
            volume_mode='grid',
            figsize=figsize,
            **merge(self._show_args, kwargs),
        )

    # --------------------------------------------------
    # REPR
    # --------------------------------------------------
    def __repr__(self) -> str:
        return f"{self.__class__.__name__}{self.as_tensor().__repr__()[6:]}"

