def detect_source(data):

    if callable(data):
        return "callable"

    if isinstance(data, pd.DataFrame):
        return "dataframe"

    if isinstance(data, (list, tuple)):
        return "list"

    if isinstance(data, str):

        if data.endswith(".csv"):
            return "csv"

        if Path(data).is_dir():
            return "folder"

    raise ValueError("Cannot detect data source")

